// =============================================
// Watchdog: verify all workflows are running
// and system is healthy
// =============================================

const checks = [];

// 1. Check Bybit API connectivity
try {
  const isTestnet = ($env.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
  const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}/v5/market/time`
  });
  checks.push({
    name: 'Bybit API',
    status: resp.retCode === 0 ? 'OK' : 'ERROR',
    detail: resp.retCode === 0 ? 'Connected' : resp.retMsg
  });
} catch(e) {
  checks.push({ name: 'Bybit API', status: 'DOWN', detail: e.message });
}

// 2. Check OpenRouter API connectivity (Claude via OpenRouter)
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${$env.OPENROUTER_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: $env.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-20250514',
      max_tokens: 10,
      messages: [{ role: 'user', content: 'ping' }]
    }
  });
  checks.push({
    name: 'OpenRouter (Claude)',
    status: resp.choices ? 'OK' : 'ERROR',
    detail: 'Connected'
  });
} catch(e) {
  checks.push({ name: 'OpenRouter (Claude)', status: 'DOWN', detail: e.message });
}

// 3. Check environment variables
const requiredEnvs = [
  'BYBIT_API_KEY', 'BYBIT_API_SECRET', 'OPENROUTER_API_KEY',
  'TELEGRAM_BOT_TOKEN', 'TELEGRAM_CHAT_ID'
];
const missingEnvs = requiredEnvs.filter(e => !$env[e]);
checks.push({
  name: 'Environment',
  status: missingEnvs.length === 0 ? 'OK' : 'WARNING',
  detail: missingEnvs.length === 0 ? 'All set' : `Missing: ${missingEnvs.join(', ')}`
});

// 4. Check bot stopped flag
const store = $getWorkflowStaticData('global');
checks.push({
  name: 'Bot Status',
  status: store.botStopped ? 'STOPPED' : 'RUNNING',
  detail: store.botStopped ? `Stopped at ${new Date(store.stoppedAt).toLocaleString('ru-RU')}` : 'Active'
});

// Determine overall health
const hasErrors = checks.some(c => c.status === 'DOWN' || c.status === 'ERROR');
const hasWarnings = checks.some(c => c.status === 'WARNING' || c.status === 'STOPPED');

return [{
  json: {
    checks,
    healthy: !hasErrors,
    hasWarnings,
    needsAlert: hasErrors
  }
}];

const data = $input.first().json;

let msg = '⚠️ <b>Watchdog Alert</b>\n\n';

for (const check of data.checks) {
  const emoji = {
    'OK': '✅', 'ERROR': '❌', 'DOWN': '🔴',
    'WARNING': '⚠️', 'STOPPED': '⛔', 'RUNNING': '🟢'
  }[check.status] || '❓';

  msg += `${emoji} <b>${check.name}:</b> ${check.status}\n`;
  msg += `   ${check.detail}\n\n`;
}

if (!data.healthy) {
  msg += '\n🚨 <b>ВНИМАНИЕ: Система работает с ошибками!</b>\n';
  msg += 'Торговля приостановлена до устранения проблем.\n';
}

msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message: msg } }];
